	@Test
	void statementLeafNeverBorrowsContextButKeepsLogicalAndObjectInputs() {
		IRI subject = VF.createIRI("urn:work:subject");
		IRI absentGraph = VF.createIRI("urn:work:absentGraph");
		Value object = VF.createLiteral("witness");
		Statement statement = VF.createStatement(subject, PREDICATE, object);
		AtomicBoolean sawObjectLookup = new AtomicBoolean();
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
					Resource... contexts) {
				boolean defaultIncluded = contexts.length == 0;
				for (Resource graph : contexts) {
					defaultIncluded |= graph == null;
				}
				sawObjectLookup.set(o != null);
				boolean matches = defaultIncluded && (s == null || s.equals(subject))
						&& (p == null || p.equals(PREDICATE)) && (o == null || o.equals(object));
				return new CloseableIteratorIteration<>(
						(matches ? List.of(statement) : List.<Statement>of()).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS,
				Var.of("subject", subject, true, true), Var.of("predicate", PREDICATE, true, true), Var.of("o"),
				Var.of("g"));
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		StatementPatternQueryEvaluationStep step = new StatementPatternQueryEvaluationStep(pattern, context, source);
		assertThat(step.supportsPhysicalLookups()).isTrue();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			BindingFrameBindings.Scope scope = new BindingFrameBindings.Scope();
			invocation.root.registerLookupInputs(scope, ignored -> true);
			for (int scenario = 0; scenario < 3; scenario++) {
				MutableBindingSet logical = context.createBindingSet();
				MutableBindingSet probe = context.createBindingSet();
				if (scenario == 0) {
					probe.addBinding("g", absentGraph);
				} else if (scenario == 1) {
					logical.addBinding("g", absentGraph);
				} else {
					probe.addBinding("o", object);
				}
				BindingSet input = BindingFrameBindings.push(scope, logical, probe, context, invocation.root);
				try (CloseableIteration<BindingSet> rows = step.evaluate(input)) {
					if (scenario == 1) {
						assertThat(rows.hasNext()).as("genuine logical graph input restricts the lookup").isFalse();
					} else {
						assertThat(rows.hasNext()).isTrue();
						assertThat(rows.next().getValue("o")).isEqualTo(object);
						assertThat(rows.hasNext()).isFalse();
					}
				}
			}
		}
		assertThat(sawObjectLookup).isTrue();
		StatementPattern contextOnly = new StatementPattern(Var.of("s", subject, true, true),
				Var.of("p", PREDICATE, true, true), Var.of("o", object, true, true), Var.of("g"));
		assertThat(new StatementPatternQueryEvaluationStep(contextOnly, context, source).supportsPhysicalLookups())
				.isFalse();
		StatementPattern repeated = new StatementPattern(Var.of("g"), Var.of("p", PREDICATE, true, true),
				Var.of("o", object, true, true), Var.of("g"));
		assertThat(new StatementPatternQueryEvaluationStep(repeated, context, source).supportsPhysicalLookups())
				.isFalse();
	}

	@Test
	void repeatedValuedVariableRespectsCertifiedProbesAndJoinCompatibility() {
		CountingSource source = new CountingSource(0);
		Value witness = VF.createLiteral("witness");
		source.statements.add(VF.createStatement(PREDICATE, PREDICATE, witness));
		IRI other = VF.createIRI("urn:work:other");
		MapBindingSet matching = new MapBindingSet();
		matching.addBinding("x", PREDICATE);
		MapBindingSet conflicting = new MapBindingSet();
		conflicting.addBinding("x", other);
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingNames(Set.of("x"));
		left.setBindingSets(List.of(matching, conflicting, new MapBindingSet()));
		StatementPattern leaf = new StatementPattern(Var.of("x"),
				Var.of("x", PREDICATE, false, false), Var.of("o"));
		Join owner = new Join(left, leaf);
		var allowed = QueryEvaluationUtility.preparedScopedLookupInputs(owner);
		assertThat(allowed).isNotNull();
		assertThat(allowed.test("x")).isTrue();

		AtomicBoolean sawBorrowedConflict = new AtomicBoolean();
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null) {
			@Override
			public java.util.function.Function<BindingSet, Value> getValue(String name) {
				var getter = super.getValue(name);
				return bindings -> {
					Value value = getter.apply(bindings);
					if ("x".equals(name) && other.equals(value)) {
						sawBorrowedConflict.set(true);
					}
					return value;
				};
			}
		};
		StatementPatternQueryEvaluationStep step = new StatementPatternQueryEvaluationStep(leaf, context, source);
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			BindingFrameBindings.Scope scope = new BindingFrameBindings.Scope();
			invocation.root.registerLookupInputs(scope, allowed);
			for (int scenario = 0; scenario < 3; scenario++) {
				MutableBindingSet logical = context.createBindingSet();
				if (scenario == 1) {
					logical.addBinding("x", PREDICATE);
				}
				MutableBindingSet probe = context.createBindingSet();
				probe.addBinding("x", scenario == 2 ? PREDICATE : other);
				BindingSet input = BindingFrameBindings.push(scope, logical, probe, context, invocation.root);
				try (CloseableIteration<BindingSet> rows = step.evaluate(input)) {
					if (scenario == 0) {
						assertThat(rows.hasNext()).as("conflicting certified lookup").isFalse();
					} else {
						assertThat(rows.hasNext()).as("compatible logical or borrowed input").isTrue();
						BindingSet result = rows.next();
						assertThat(result.getValue("x")).isEqualTo(PREDICATE);
						assertThat(result.getValue("o")).isEqualTo(witness);
						assertThat(rows.hasNext()).isFalse();
					}
				}
			}
		}
		assertThat(sawBorrowedConflict).isTrue();

		MapBindingSet joined = new MapBindingSet();
		joined.addBinding("x", PREDICATE);
		joined.addBinding("o", witness);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		assertThat(evaluate(strategy, owner.clone())).containsExactlyInAnyOrder(joined, joined);
		assertThat(evaluate(strategy, new LeftJoin(left.clone(), leaf.clone())))
				.containsExactlyInAnyOrder(joined, joined, conflicting);
	}

