	@ParameterizedTest(name = "cycles={0}")
	@ValueSource(ints = { 8, 16 })
	void foafShapedJoinWithOwnerFilterUsesBoundLookups(int cycles) {
		CountingSource source = new CountingSource(cycles, true);
		AtomicInteger comparisons = new AtomicInteger();
		DefaultEvaluationStrategy strategy = countingStrategy(source, comparisons);
		TupleExpr first = pattern("a", "b");
		TupleExpr second = new Filter(pattern("b", "c"),
				new Compare(Var.of("a"), Var.of("c"), Compare.CompareOp.NE));
		Join inner = new Join(second, pattern("c", "a"));
		Join outer = new Join(first, inner);
		List<BindingSet> actual = evaluate(strategy, outer);
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < cycles; i++) {
			IRI a = node("a", i);
			IRI b = node("b", i);
			IRI c = node("c", i);
			expected.add(row(a, b, c));
			expected.add(row(b, c, a));
			expected.add(row(c, a, b));
		}
		System.out.printf("foaf-shaped-work cycles=%d outer=%s inner=%s comparisons=%d boundLookups=%d "
				+ "unboundLookups=%d returnedCandidates=%d rows=%d%n", cycles, outer.getAlgorithmName(),
				inner.getAlgorithmName(), comparisons.get(), source.boundLookups.get(), source.unboundLookups.get(),
				source.returned.get(), actual.size());
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(comparisons.get()).as("condition work for %d disjoint cycles", cycles)
				.isLessThanOrEqualTo(6 * cycles);
		assertThat(source.unboundLookups.get()).as("only the first cycle edge needs a full scan").isEqualTo(1);
		assertThat(source.boundLookups.get()).as("subsequent shared edges use bound lookups").isPositive();
	}

