	@Test
	void authorizedFilterReadDoesNotDischargeAnExtensionTargetOfTheSameName() {
		ClosingLookupSource source = new ClosingLookupSource();
		IRI owner = node("owner", 0);
		IRI b = node("b", 0);
		IRI c = node("c", 0);
		IRI y = node("y", 0);
		source.statements.add(VF.createStatement(b, SECOND_PREDICATE, c));
		source.statements.add(VF.createStatement(node("different", 0), CLOSING_PREDICATE, y));
		MapBindingSet input = new MapBindingSet();
		input.addBinding("a", owner);
		input.addBinding("b", b);
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(input));
		TupleExpr filter = new Filter(pattern("b", SECOND_PREDICATE, "c"), new Bound(Var.of("a")));
		Extension overwrite = new Extension(pattern("a", CLOSING_PREDICATE, "y"),
				new ExtensionElem(new ValueConstant(owner), "a"));
		List<BindingSet> actual = evaluate(new DefaultEvaluationStrategy(source, null),
				new Join(left, new Join(filter, overwrite)));
		MapBindingSet expected = new MapBindingSet();
		expected.addBinding("a", owner);
		expected.addBinding("b", b);
		expected.addBinding("c", c);
		expected.addBinding("y", y);
		assertThat(actual).containsExactly(expected);
		assertThat(source.closingOpens).hasValue(1);
	}

	@Test
	void cycleOwnerProofPermitsAnAssuredNearerFilterInput() {
		TupleExpr first = pattern("a", "b");
		TupleExpr second = new Filter(pattern("b", "c"), new Bound(Var.of("a")));
		Filter third = new Filter(pattern("c", "d"),
				new And(new Bound(Var.of("a")), new Bound(Var.of("b"))));
		Join near = new Join(second, new Join(third, pattern("d", "a")));
		Join outer = new Join(first, near);
		var edges = BindingScopePolicy.filterInputEdges(third);
		assertThat(edges).anySatisfy(edge -> {
			assertThat(edge.owner()).isSameAs(near);
			assertThat(edge.names()).contains("b");
		});
		assertThat(edges).anySatisfy(edge -> {
			assertThat(edge.owner()).isSameAs(outer);
			assertThat(edge.names()).contains("a", "b");
		});
		var proof = QueryEvaluationUtility.preparedScopedLookupInputs(outer);
		assertThat(proof).isNotNull();
		System.out.printf("cycle-owner-proof outerA=%s outerB=%s%n", proof.test("a"), proof.test("b"));
		assertThat(proof.test("a")).isTrue();
		assertThat(proof.test("b"))
				.as("the nearer owner assures b before the FILTER and the outer join requires compatibility")
				.isTrue();
	}

	@ParameterizedTest(name = "chains={0}, nesting={1}")
	@CsvSource({ "8,1", "16,1", "8,4", "16,4" })
	void assuredNearerOwnerUsesOuterCompatibleLookup(int chains, int nesting) {
		CountingSource source = new CountingSource(chains);
		AtomicInteger comparisons = new AtomicInteger();
		List<BindingSet> inputs = new ArrayList<>();
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < chains; i++) {
			MapBindingSet input = new MapBindingSet();
			input.addBinding("a", node("outer", i));
			input.addBinding("b", node("a", i));
			inputs.add(input);
			expected.add(row(node("outer", i), node("a", i), node("b", i)));
		}
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(inputs);
		Filter condition = new Filter(new SingletonSet(),
				new Compare(Var.of("a"), Var.of("b"), Compare.CompareOp.NE));
		TupleExpr right = new Join(pattern("b", "c"), condition);
		for (int i = 1; i < nesting; i++) {
			right = new Join(new SingletonSet(), right);
		}
		List<BindingSet> actual = evaluate(countingStrategy(source, comparisons), new Join(left, right));
		System.out.printf("assured-near-owner chains=%d nesting=%d comparisons=%d bound=%d unbound=%d rows=%d%n",
				chains, nesting, comparisons.get(), source.boundLookups.get(), source.unboundLookups.get(),
				actual.size());
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(comparisons.get()).as("only owner-compatible candidates reach the nearer FILTER").isEqualTo(chains);
		assertThat(source.boundLookups.get()).isEqualTo(chains);
		assertThat(source.unboundLookups.get()).isZero();
	}

