	@Test
	void optionalFallbackRemainsAVetoForNearerOwnerLookup() {
		MapBindingSet outerRow = new MapBindingSet();
		outerRow.addBinding("b", node("outer", 0));
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(outerRow));
		MapBindingSet incompatible = new MapBindingSet();
		incompatible.addBinding("b", node("inner", 0));
		BindingSetAssignment local = new BindingSetAssignment();
		local.setBindingSets(List.of(incompatible));
		LeftJoin optional = new LeftJoin(new SingletonSet(), local);
		Join near = new Join(optional, new Filter(new SingletonSet(), new Bound(Var.of("b"))));
		Join outer = new Join(left, near);
		List<BindingSet> actual = evaluate(new DefaultEvaluationStrategy(new CountingSource(0), null), outer);
		assertThat(actual).isEmpty();
		var proof = QueryEvaluationUtility.preparedScopedLookupInputs(outer);
		assertThat(proof == null || !proof.test("b"))
				.as("OPTIONAL fallback must not become compatible after an injected b")
				.isTrue();
	}

	@Test
	void ownerFilterCannotPushThroughAnExtensionThatOverwritesTheLookupName() {
		CountingSource source = new CountingSource(2);
		DefaultEvaluationStrategy strategy = countingStrategy(source, new AtomicInteger());
		IRI selected = node("a", 0);
		MapBindingSet input = new MapBindingSet();
		input.addBinding("x", selected);
		input.addBinding("owner", selected);
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(input));
		Extension extension = new Extension(pattern("x", "y"),
				new ExtensionElem(new ValueConstant(selected), "x"));
		TupleExpr right = new Filter(extension, new Bound(Var.of("owner")));
		List<BindingSet> actual = evaluate(strategy, new Join(left, right));
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < 2; i++) {
			for (String role : List.of("b", "c")) {
				MapBindingSet row = new MapBindingSet();
				row.addBinding("x", selected);
				row.addBinding("owner", selected);
				row.addBinding("y", node(role, i));
				expected.add(row);
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
	}

	@ParameterizedTest(name = "cycles={0}")
	@ValueSource(ints = { 8, 16 })
	void nestedFiltersComposeLookupsThroughAnIndependentJoin(int cycles) {
		CountingSource source = new CountingSource(cycles, true);
		DefaultEvaluationStrategy strategy = countingStrategy(source, new AtomicInteger());
		Join inner = new Join(pattern("b", "c"), pattern("c", "d"));
		TupleExpr right = new Filter(new Filter(inner, new Bound(Var.of("a"))), new Bound(Var.of("a")));
		List<BindingSet> actual = evaluate(strategy, new Join(pattern("a", "b"), right));
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < cycles; i++) {
			IRI a = node("a", i);
			IRI b = node("b", i);
			IRI c = node("c", i);
			for (BindingSet edge : List.of(row(a, b, c), row(b, c, a), row(c, a, b))) {
				QueryBindingSet row = new QueryBindingSet(edge);
				row.addBinding("d", edge.getValue("a"));
				expected.add(row);
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(source.unboundLookups.get()).isEqualTo(1);
		assertThat(source.returned.get()).isEqualTo(9 * cycles);
	}

	@Test
	void compositeRegionDoesNotReopenAnIndependentValuesProducerPerCaller() {
		CountingSource source = new CountingSource(8, true);
		MapBindingSet marker = new MapBindingSet();
		marker.addBinding("marker", node("marker", 0));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(marker));
		AtomicInteger opened = new AtomicInteger();
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null) {
			@Override
			public QueryEvaluationStep precompile(TupleExpr expression, QueryEvaluationContext context) {
				QueryEvaluationStep step = super.precompile(expression, context);
				return expression instanceof BindingSetAssignment ? input -> {
					opened.incrementAndGet();
					return step.evaluate(input);
				} : step;
			}
		};
		TupleExpr inner = new Join(values, pattern("b", "c"));
		List<BindingSet> actual = evaluate(strategy,
				new Join(pattern("a", "b"), new Filter(inner, new Bound(Var.of("a")))));
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < 8; i++) {
			IRI a = node("a", i);
			IRI b = node("b", i);
			IRI c = node("c", i);
			for (BindingSet edge : List.of(row(a, b, c), row(b, c, a), row(c, a, b))) {
				QueryBindingSet row = new QueryBindingSet(edge);
				row.addBinding("marker", marker.getValue("marker"));
				expected.add(row);
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(opened).as("the independent VALUES producer is replayed once").hasValue(1);
	}

